];

// Elige el hotel más barato del input (items ya normalizados)
// Campos esperados: hotel_name, provider, currency, total_price (o price), booking_url

function pickPrice(h) {
  const candidates = [
    h.total_price, h.totalPrice,
    h.price, h.amount,
    h.pricing?.total,
    h.rate?.total,
  ];
  const v = candidates.find(x => x !== undefined && x !== null && x !== "");
  if (v === undefined) return null;

  const s = String(v).trim().replace(/[^\d.,-]/g, "");
  const normalized = (s.includes(",") && !s.includes("."))
    ? s.replace(",", ".")
    : s.replace(/,/g, "");
  const n = Number(normalized);
  return Number.isFinite(n) ? n : null;
}

const hotels = $input.all().map(i => i.json);
const priced = hotels.map(h => ({...h, _price: pickPrice(h)})).filter(h => h._price !== null);

if (priced.length === 0) {
  return [{
    json: {
      status: "error",
      message: "No se encontraron precios válidos para comparar.",
      received_count: hotels.length,
      sample: hotels.slice(0, 3),
    }
  }];
}

priced.sort((a,b) => a._price - b._price);
const winner = priced[0];

return [{
  json: {
    status: "ok",
    cheapest: {
      hotel_name: winner.hotel_name || winner.name || "Unknown",
      provider: winner.provider || winner.source || "Unknown",
      currency: winner.currency || "Unknown",
      total_price: winner._price,
      booking_url: winner.booking_url || winner.url || null,
    },
    top5: priced.slice(0,5).map(h => ({
      hotel_name: h.hotel_name || h.name || "Unknown",
      provider: h.provider || h.source || "Unknown",
      currency: h.currency || "Unknown",
      total_price: h._price,
      booking_url: h.booking_url || h.url || null,
    })),
    compared_count: priced.length
  }
}];
